import{_ as n,l as o,o as e,c as l,v as t,p,x as i,d as s,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"概率加权","description":"","frontmatter":{"title":"概率加权","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/probability-weighting.md","filePath":"econ/probability-weighting.md","lastUpdated":1789023840000}'),h={name:"econ/probability-weighting.md"};function E(m,a,_,A,T,P){const r=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="概率加权" tabindex="-1">概率加权 <a class="header-anchor" href="#概率加权" aria-label="Permalink to &quot;概率加权&quot;">​</a></h1><div class="epigraph"><p>决策权重不是概率：小概率被抬高，中高概率被压低，四重模式把保险与彩票放进同一张图。</p><footer>—— Tversky and Kahneman, Advances in Prospect Theory: Cumulative Representation of Uncertainty, Journal of Risk and Uncertainty, 1992；Prelec, Econometrica 1998</footer></div><p><a href="/econ/loss-aversion-reference">上一课</a>钉住 \\(\\lambda\\)。本课缺口是 \\(v\\) 解释不了的部分：人对概率的扭曲。不重写拐折。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>原前景理论的 \\(\\pi(p)\\) 直接加权各结果，多结果时可能违反一阶随机占优。Tversky 与 Kahneman（1992）改成累积前景理论（CPT）：对排序后的结果用累积概率的加权差，类似秩依赖。Prelec（1998）给出单参数权重 \\(w(p)=\\exp\\{-(-\\ln p)^\\alpha\\}\\)，\\(\\alpha\\lt 1\\) 时倒 S 形：小 \\(p\\) 高估、大 \\(p\\) 低估。四重模式：收益–大概率厌恶（确定效应）、收益–小概率寻求（彩票）、损失–大概率寻求、损失–小概率厌恶（保险）。</p><p>阿莱共同结果效应是确定效应的近亲：把确定的收益换成高概率，偏好翻转。缺口是把「独立性失败」翻译成 \\(w(p)\\)，而不是再证 vNM 表示定理。</p><p><span class="marginnote">秩依赖：权重打在累积分布的分位上，不是打在单个原子上。极好与极坏的尾部被抬高，中间被压低。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>CPT：正结果按累积从好到坏加权，负结果按累积从坏到好加权，各乘 \\(v\\)。本课不把函数拟合写成作业。经验含义：人以过高价格买尾部（彩票、虚值期权式的直觉），又以过高价格买灾难保险。资产定价的尾部偏好后段再接，这里只给家庭选择。</p>',9)),(e(),p(c,null,{default:i(()=>[d(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PI%5B%221979%3A%20pi(p)%20%E9%80%90%E7%82%B9%E5%8A%A0%E6%9D%83%22%5D%20--%3E%20CPT%5B%221992%3A%20%E7%B4%AF%E7%A7%AF%20%2F%20%E7%A7%A9%E4%BE%9D%E8%B5%96%22%5D%0A%20%20CPT%20--%3E%20S%5B%22%E5%80%92%20S%3A%20%E5%B0%8F%20p%20%E9%AB%98%E4%BC%B0%22%5D%0A%20%20S%20--%3E%20FOUR%5B%22%E5%9B%9B%E9%87%8D%E6%A8%A1%E5%BC%8F%3A%20%E4%BF%9D%E9%99%A9%E4%B8%8E%E5%BD%A9%E7%A5%A8%E5%B9%B6%E5%AD%98%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是决策权重对概率的非线性。线性 \\(\\mathbb{E}\\) 是 vNM 的独立性；弯的 \\(w\\) 破坏独立性，保留一阶占优（在 CPT 下）。人不是算错了客观 \\(p\\)（那是信念课），而是即使知道 \\(p\\) 也用 \\(w(p)\\) 当权重。与现时偏差类似：不是信息集错了，是加总函数错了。</p><p>实验室常用确定效应：0.99 的高收益对 1 的确定，人抱住确定。这与企业「做平」对冲的直觉不同，不要写成公司金融。</p><p>Prelec 权重把倒 S 收成一个 \\(\\alpha\\)，便于对照实验，不是新的独立性公理。CPT 的累积构造保证：改进最坏结果不会被权重搞成变差，原 \\(\\pi(p)\\) 没有这条。阿莱共同结果：在公共的 0.89 概率上再叠同一结果，vNM 不应改排序；人改了，因为确定的 1 变成了 0.11 对 0.12 的加权比较。本课用这句话接已有的阿莱课，不重证表示定理。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>权重函数在经验上不稳定，依赖陈述方式（频率还是概率、是否有经验抽样）。经验抽样往往减小平概率高估。本课不把所有保险需求归因于 \\(w\\)：风险厌恶与加载同样存在。也不估计期权隐含的尾部。</p><p>后课默认：说到概率加权，指倒 S 的 \\(w\\) 或 CPT 累积权重；心理账户回答的是哪些结果被放进同一个前景。</p><p>CPT 用累积权重保住占优；倒 S 给出四重模式。独立性失败被写成 \\(w(p)\\neq p\\)。</p><p>人可以知道客观 \\(p\\) 仍用 \\(w\\)；那与信念课的错估 \\(p\\) 分工。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CPT 用累积权重修复多结果占优，倒 S 产生四重模式。</li><li>独立性失败被写成 \\(w(p)\\neq p\\)，不重推 vNM。</li><li>保险与彩票并存是加权与损失厌恶的分工，不是矛盾。</li><li>确定效应是阿莱共同结果的近亲。</li><li>经验抽样往往会减小平概率高估。</li><li>出处：Tversky and Kahneman, 1992；Prelec, <em>Econometrica</em> 1998。</li></ul>',11))])}const f=n(h,[["render",E]]);export{b as __pageData,f as default};
